python -m playwright install chromium && PYTHONPATH=computer python - <<'PY'
import json, time
from control_plane.live_telemetry import live_emit, live_flush
from server import browser

live_emit('runtime','Browser test started','Opening chatgpt.com','running',dedupe_key='browser-test:start')
b = browser()

def interact():
    page = b._ensure()
    page.goto('https://chatgpt.com/', wait_until='domcontentloaded', timeout=45000)
    title = page.title()
    body = page.locator('body').inner_text(timeout=10000)
    low = (title + '\n' + body).lower()
    challenge = any(x in low for x in ['captcha','verify you are human','checking your browser','security challenge','attention required'])
    if challenge:
        return {'status':'blocked','reason':'human verification','title':title,'url':page.url}
    for label in ['Accept all','Accetta tutto','Continue','Continua']:
        try:
            btn = page.get_by_role('button', name=label).first
            if btn.count():
                btn.click(timeout=1500)
                break
        except Exception:
            pass
    selectors = ['#prompt-textarea','textarea[placeholder*="Message"]','textarea','div[contenteditable="true"]']
    box = None
    for sel in selectors:
        try:
            loc = page.locator(sel).first
            if loc.count() and loc.is_visible():
                box = loc
                break
        except Exception:
            pass
    if box is None:
        body2 = page.locator('body').inner_text(timeout=5000)
        if 'log in' in body2.lower() or 'sign up' in body2.lower() or 'accedi' in body2.lower():
            return {'status':'blocked','reason':'login required','title':title,'url':page.url}
        return {'status':'blocked','reason':'composer not found','title':title,'url':page.url}
    prompt = 'Ciao! Questo è un test automatico di Airi-PC. Rispondi soltanto: AIRI_BROWSER_OK'
    box.click(timeout=5000)
    try:
        box.fill(prompt)
    except Exception:
        page.keyboard.insert_text(prompt)
    page.keyboard.press('Enter')
    sent_at = time.time()
    while time.time() - sent_at < 25:
        page.wait_for_timeout(1000)
        text = page.locator('body').inner_text(timeout=5000)
        if 'AIRI_BROWSER_OK' in text:
            return {'status':'replied','reply_marker':'AIRI_BROWSER_OK','title':page.title(),'url':page.url}
    text = page.locator('body').inner_text(timeout=5000)
    return {'status':'sent_no_marker','tail':text[-1000:],'title':page.title(),'url':page.url}

try:
    result = b.call(interact)
    live_emit('runtime','ChatGPT opened',result.get('url','chatgpt.com'),'completed',dedupe_key='browser-test:opened')
    if result.get('status') == 'replied':
        live_emit('runtime','ChatGPT replied',result.get('reply_marker'),'completed',dedupe_key='browser-test:reply')
    elif result.get('status') == 'sent_no_marker':
        live_emit('runtime','Message sent to ChatGPT','No AIRI_BROWSER_OK marker seen within 25s','verifying',dedupe_key='browser-test:sent')
    else:
        live_emit('runtime','ChatGPT interaction blocked',result.get('reason','unknown'),'blocked',dedupe_key='browser-test:blocked')
    print(json.dumps(result, ensure_ascii=False))
finally:
    live_flush(10.0)
PY
